#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"static char* daysofweek[7] ={ "ПН.", "ВТ.", "СР.", "ЧТ.", "ПТ.", "СБ.", "ВС." };typedef struct : public SPROLOZ  {	int nHS;    //определяет вид и содержание отображаемой информации	DWORD bkColor; //фон экрана	char szKey[32];    //код для отображения    char szNumber[32]; //номер для отображения  }   Queue_PAS_05;void DrawTextData(Queue_PAS_05 *p, DefinePaint){  ::Rectangle( hDC, p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );  int HFild=(p->mRect.right-p->mRect.left)/27;  int VFild=(p->mRect.bottom-p->mRect.top)/14;  int HDelta=(p->mRect.bottom-p->mRect.top)/70;  RECT rect;  rect.left=p->mRect.left+HFild;  rect.top=p->mRect.top+VFild;  rect.right=p->mRect.right;  int quarterofheight=(p->mRect.bottom-p->mRect.top-VFild)/4;  rect.bottom=p->mRect.top+quarterofheight;  char str[256];  ::DrawText(hDC, "ПАС-05", -1, &rect, DT_SINGLELINE|DT_VCENTER|DT_LEFT );  RECT rect2(rect);  rect2.left+=HFild*10;  sprintf_s(str, _countof(str)-1, "%8.8s  %3.3s", p->szKey, p->szNumber );  ::DrawText(hDC, str, -1, &rect2, DT_SINGLELINE|DT_VCENTER|DT_LEFT );  __time64_t Time = ::GiveModelTime();  struct tm TM;  _localtime64_s( &TM, &Time );  rect.top=rect.bottom+HDelta;  rect.bottom=rect.top+quarterofheight;  ::DrawText(hDC, "Дата:", -1, &rect, DT_SINGLELINE|DT_VCENTER|DT_LEFT );  sprintf_s(str, _countof(str)-1, "%2.2d:%2.2d:%2.2d   %3.3s", TM.tm_mday, TM.tm_mon+1, TM.tm_year%100, daysofweek[(TM.tm_wday-1)%7]);   rect2=rect;  rect2.left+=HFild*10;  ::DrawText(hDC, str, -1, &rect2, DT_SINGLELINE|DT_VCENTER|DT_LEFT );  rect.top=rect.bottom+HDelta;  rect.bottom=rect.top+quarterofheight;  ::DrawText(hDC, "Время:", -1, &rect, DT_SINGLELINE|DT_VCENTER|DT_LEFT );  rect2=rect;  rect2.left+=HFild*10;  sprintf_s(str, _countof(str)-1, "%2.2d:%2.2d:%2.2d", TM.tm_hour, TM.tm_min, TM.tm_sec); //tm_wday  ::DrawText(hDC, str, -1, &rect2, DT_SINGLELINE|DT_VCENTER|DT_LEFT );}int PaintPAS_05(DefinePaint){  QueueP(Queue_PAS_05);  bool  State=false; //состояние управляющей переменной прописаной в сценарии  if ( p->nHS >= 0 )    {    CShHS& Sh = (CShHS&)q.m_pPipe->SH(p->nHS);    if ( Sh.RetCode == CShBase::rcOK )		State = Sh.mOn;     }  if(!State)    {//рисуем текст с нормальным фоном    CMyBrush brush (hDC, p->bkColor, true);     DrawTextData(p, hDC, szQueue, q, beginQ, u);    }  else  {//рисуем знакоместа символов с подсветкой фона  CMyBrush brush(hDC, RGB(255, 86, 0) , true);   ::Rectangle( hDC, p->mRect.left, p->mRect.top, p->mRect.right, p->mRect.bottom );  int HFild=(p->mRect.right-p->mRect.left)/24;  int VFild=(p->mRect.bottom-p->mRect.top)/12;  int HDelta=(p->mRect.bottom-p->mRect.top)/70;  int quarterofheight=(p->mRect.bottom-p->mRect.top-VFild)/4;  int NVLine=(p->mRect.right-p->mRect.left)/44;  {   int x=p->mRect.left+HFild;   int y=p->mRect.top+VFild;   CMyPen pen(hDC, RGB(0, 0, 0), 0, PS_DOT);    for(int ii=0; ii<18; ii++)    {       for(int jj=0; jj<NVLine; jj++)		  {		  ::MoveToEx(hDC, x, y, NULL);		  ::LineTo(hDC, x, p->mRect.bottom-VFild);		  x+=2;		  }		  x+=2;    }  }  {   int x=p->mRect.left+HFild;   int y=p->mRect.top+quarterofheight+(2*VFild/3);   CMyPen pen(hDC, RGB(255, 86, 0), 2);    for(int ii=0; ii<3; ii++)    {	  ::MoveToEx(hDC, x, y, NULL);	  ::LineTo(hDC, p->mRect.right-HDelta, y);	  y+=quarterofheight;    }   }  }  return 1;}void AddPAS_05(DefineTegs){  AddQueueEx(Queue_PAS_05);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPAS_05;  //  char szColor[32];  STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },	{ 'S', "bkcolor", szColor, _countof(szColor) -1  },	{ 'S', "key", p->szKey, _countof(p->szKey) -1 },    { 'S', "number", p->szNumber, _countof(p->szNumber) -1  },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->nHS = def.AddKind(id_HS, teg[0].value);  p->bkColor=::ParserColors(szColor);}